#!/bin/sh
#
# Generated by the sh backend. Non-POSIX constructs used:
# - 'local': variable scoping (POSIX sh lacks local, but dash/bash/zsh support it)
# - Array emulation (name_0, name_len): arrays are not POSIX
# - '(( ))' arithmetic: required for integer comparison in conditions
# - 'grep -P' helper: PCRE not in POSIX, checked at runtime
#
grep pattern /dev/null || echo 'No matches found'
echo 'HELLO world' | grep -i hello
printf '%b\n' 'line1\nline2\nline3' | grep -v line2
printf '%b\n' 'first\nsecond\nthird' | grep -n second
printf '%b\n' 'match\nno match\nmatch again' | grep -c match
echo 'text with pattern123 in it' | grep -o 'pattern[0-9]\+'
matched="$(printf '%s\n' test | grep -c '.*')"
printf '%s\n' "  grep_exit: $?"
printf '%s\n' "  match_count: $matched"
